const std = @import("std"); const erru = @import("er-erro-type.zig"); const spec = @import("pa-spec-read.zig"); const fspc = @import("nt-fetc-spec.zig"); const pipe = @import("ru-page-fetc.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const urln = @import("ut-urlz-norm.zig"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const exit = @import("ct-exit-code.zig");
pub fn rep2(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Dbzz, dirz: []const u8, text: []const u8, parm: []const u8, priv: bool) !pipe.Outc { const rawz = try spec.specRead(aren, text); const spcz = try spec.specFill(aren, rawz, parm); _ = urln.urlzSpli(spcz.urlz) catch return error.BadSpec; const resp = try fspc.specFetc(gpaz, aren, iozz, spcz, .{ .time_mill = conf.fetc_time_seco * 1000, .body_maxz = conf.fetc_body_maxz, .priv = priv }); if (resp.code == 401 or resp.code == 403) return error.StaleSpec; if (resp.code == 429) return error.Blocked; const key2 = try urln.urlzNorm(aren, try spec.urlzSafe(aren, spcz.urlz)); const prev = try inde.pageGetz(dbzz, aren, key2); return pipe.pageSave(aren, iozz, conf, dbzz, dirz, key2, prev, .{ .code = resp.code, .ctyp = resp.ctyp, .body = resp.body }); }
pub fn runzRepl(ctx2: *const ctx3.Ctxz) !u8 { if (ctx2.args.spec.len == 0) return error.BadUsage; const text = std.Io.Dir.cwd().readFileAlloc(ctx2.iozz, ctx2.args.spec, ctx2.allo, .limited(4 << 20)) catch return erru.usag("cannot read --spec file", ctx2.args.spec); const spcz = try spec.specFill(ctx2.allo, try spec.specRead(ctx2.allo, text), ctx2.args.parm); const part = urln.urlzSpli(spcz.urlz) catch return error.BadSpec; if (!ctx2.args.live) { try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "dry-run | replay {s} https://{s}/... | {d} headers, body {d} bytes | own IP, no vendor, no spend | add --live to send", .{ spcz.meth, part.host, spcz.hdrs.len, spcz.body.len })); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const outc = try rep2(ctx2.init.gpa, ctx2.allo, ctx2.iozz, ctx2.conf, &dbzz, ctx2.dirz, text, ctx2.args.parm, false); const plai = try std.fmt.allocPrint(ctx2.allo, "{s} | {d} | {s} | {s} | {s}", .{ outc.stat, outc.code, outc.kind, outc.urlz, outc.hexz }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, outc, plai)); return exit.outcCode(outc.stat, outc.code); }
